const stages=[
{title:'How far does your evidence reach?',context:'A clear sentence can still say more than the facts support. Start by separating what happened from what you concluded.',label:'Fictional learner draft',draft:'Everyone should stop checking email before lunch. I tried it for a week and got much more done, so morning email is the main reason people are unproductive.',feedback:'What did you observe, and what did you assume?',button:'🔎 Examine the claim'},
{title:'One week is evidence. Of what?',context:'A personal experience can support a useful idea without proving a universal rule.',label:'The unsupported leap',draft:'“I tried it for a week” → “Everyone should stop.” What connects those two claims?',feedback:'Did your workload change that week? How did you measure getting more done? Whose work requires morning replies?',button:'✍️ See a careful revision'},
{title:'Make the claim fit the observation.',context:'Precision can strengthen an argument even when the conclusion becomes narrower.',label:'Illustrative revision',draft:'Delaying email until lunch helped me protect writing time during a one-week trial. I have not measured whether it increased my total output. For people whose mornings can stay interruption-free, a similar trial may be worth considering.',feedback:'Notice what changed: a universal claim became a bounded observation and a suggestion. No new evidence was invented.',button:'🧠 Try a fresh problem'},
{title:'Now make the judgment yourself.',context:'A library opened longer for two Saturdays. Visits rose, but it also hosted a special event. Staffing costs were not recorded. Should it permanently extend its hours?',label:'Independent practice',draft:'Consider what the trial shows, what it cannot show, and whether a smaller next step would help.',feedback:'Write first. Then use the checklist to examine your reasoning. This preview does not send your text anywhere.',button:'📝 Return to the example'}];
let step=0;const byId=id=>document.getElementById(id);function render(){const s=stages[step];byId('lesson-title').textContent=s.title;byId('lesson-context').textContent=s.context;byId('draft-label').textContent=s.label;byId('demo-draft').textContent=s.draft;byId('feedback-text').textContent=s.feedback;byId('next-step').textContent=s.button;byId('step-count').textContent=`${step+1} of 4`;byId('course-progress').style.width=`${(step+1)*25}%`;byId('exercise').hidden=step!==3;document.querySelectorAll('[data-step]').forEach(b=>{b.classList.toggle('selected',Number(b.dataset.step)===step);b.setAttribute('aria-pressed',String(Number(b.dataset.step)===step))});const page=document.querySelector('.lesson-page');page.classList.remove('changing');void page.offsetWidth;page.classList.add('changing')}
byId('next-step').addEventListener('click',()=>{step=(step+1)%4;render()});document.querySelectorAll('[data-step]').forEach(b=>b.addEventListener('click',()=>{step=Number(b.dataset.step);render()}));byId('self-check').addEventListener('click',()=>{byId('check-result').textContent=byId('attempt').value.trim()?'Self-check: Did you separate the increased visits from their possible cause? Name the missing cost information? Explain your next step? A different conclusion can still be well supported. This is a checklist, not an AI assessment.':'Write your recommendation first, then compare it with the checklist.'});const modal=byId('enrollment');document.querySelectorAll('[data-plan]').forEach(b=>b.addEventListener('click',()=>{byId('plan-name').textContent=b.dataset.plan;modal.showModal()}));document.querySelector('.close').addEventListener('click',()=>modal.close());byId('modal-sample').addEventListener('click',()=>{modal.close();byId('practice').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});byId('next-step').focus({preventScroll:true})});render();
